import java.util.*;

class Solution {
  public int[] findMaximums(int[] nums) {
    int n = nums.length;
    int[] left = new int[n], right = new int[n]; // nearest smaller element on each side
    Deque<Integer> stack = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
      while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) stack.pop();
      left[i] = stack.isEmpty() ? -1 : stack.peek();
      stack.push(i);
    }
    stack.clear();
    for (int i = n - 1; i >= 0; i--) {
      while (!stack.isEmpty() && nums[stack.peek()] >= nums[i]) stack.pop();
      right[i] = stack.isEmpty() ? n : stack.peek();
      stack.push(i);
    }
    int[] ans = new int[n];
    // nums[i] is the minimum of a window as wide as right - left - 1
    for (int i = 0; i < n; i++) {
      int len = right[i] - left[i] - 1;
      ans[len - 1] = Math.max(ans[len - 1], nums[i]);
    }
    // a value that is the minimum of a wide window also covers every narrower one
    for (int i = n - 2; i >= 0; i--) ans[i] = Math.max(ans[i], ans[i + 1]);
    return ans;
  }
}
